class Solution {
  public int maxScore(int n, int k, int[][] stayScore, int[][] travelScore) {
    int[] dp = new int[n];
    for (int d = 0; d < k; d++) {
      int[] nd = new int[n];
      for (int c = 0; c < n; c++) {
        int best = dp[c] + stayScore[d][c];
        for (int p = 0; p < n; p++) {
          int v = dp[p] + travelScore[p][c];
          if (p != c && v > best) best = v;
        }
        nd[c] = best;
      }
      dp = nd;
    }
    int ans = 0;
    for (int v : dp) ans = Math.max(ans, v);
    return ans;
  }
}
